#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

#define CWE_MAX_LEN 10
#define CWE_MAX_NUM 5

int main(int argc, char *argv[])
{
	char *line = NULL;
	size_t len = 0;
	ssize_t read;
	char *cwe_list[CWE_MAX_NUM];
	int cwe_num = 0;
	int i;

	while ((read = getline(&line, &len, stdin))!= -1) {
		char *cwe = strtok(line, " ");
		if (cwe == NULL)
			continue;
		if (strncmp(cwe, "CWE-", 4)!= 0)
			continue;
		if (cwe_num >= CWE_MAX_NUM)
			break;
		cwe_list[cwe_num] = strdup(cwe);
		cwe_num++;
	}

	printf("[");
	for (i = 0; i < cwe_num; i++) {
		if (i!= 0)
			printf(", ");
		printf("\"%s\"", cwe_list[i]);
	}
	printf("]\n");

	for (i = 0; i < cwe_num; i++)
		free(cwe_list[i]);

	return 0;
}
